const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)], esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), id=()=>crypto.randomUUID().replaceAll('-','');
let project,revision=0,dirty=false,changeCount=0,saveTimer,saving=null,saveError=false,projects=[],tab='story',selected=null,peaks=null,loopRange=null,importData=null,thumbFrames=[],currentPreview=null,suppressPauseSave=false;
const audio=$('#audio'), roles=['singing','instrument','story','reaction','gag','dance'], sections=['Intro','Verse','Pre-chorus','Chorus','Hook','Instrumental','Bridge','Outro','Ending'];
let audioPlayRequest=0;
async function playAudio(){
 const request=++audioPlayRequest;
 try{await audio.play();return true;}
 catch(e){
  // Pause, seek/source changes and a newer Play request can cancel a pending play.
  // Cancellation is normal; only the latest genuine playback failure is shown.
  if(request===audioPlayRequest&&e.name!=='AbortError')toast(e.message);
  return false;
 }
}
function pauseAudio(){++audioPlayRequest;audio.pause();}
const fmt=t=>{t=Math.max(0,Number(t)||0);return `${String(Math.floor(t/60)).padStart(2,'0')}:${(t%60).toFixed(3).padStart(6,'0')}`};
const parseTime=v=>{if(typeof v==='number')return v;const a=String(v).trim().replace(',','.').split(':').map(Number);return a.reduce((p,n)=>p*60+n,0)};
const duration=()=>project?.duration>0?project.duration:Math.max(30,...(project?.scenes||[]).map(s=>s.end),...(project?.lyrics||[]).map(s=>s.end));
const asset=aid=>project.assets.find(a=>a.id===aid), mediaUrl=a=>a?'/media/'+encodeURIComponent(a.filename):'', scene=()=>project.scenes.find(s=>s.id===selected), sceneIndex=()=>project.scenes.findIndex(s=>s.id===selected);
const opts=(values,value)=>values.map(x=>`<option value="${esc(x)}" ${x===value?'selected':''}>${esc(x)}</option>`).join('');
const field=(label,path,value,placeholder='',type='text')=>`<label>${label}<input type="${type}" ${type==='number'?'min="0" step="0.001"':''} data-path="${path}" value="${esc(value)}" placeholder="${esc(placeholder)}"></label>`;
const area=(label,path,value,placeholder='')=>`<label>${label}<textarea data-path="${path}" placeholder="${esc(placeholder)}">${esc(value)}</textarea></label>`;
