async function api(path,body,options={}){const res=await fetch(path,{...options,method:body===undefined?'GET':'POST',headers:body===undefined?options.headers:{'Content-Type':'application/json',...options.headers},body:body===undefined?undefined:JSON.stringify(body)});const data=await res.json();if(!res.ok){let e=new Error(data.error||res.statusText);e.status=res.status;throw e}return data}
async function upload(file){const res=await fetch('/api/upload',{method:'POST',headers:{'X-Filename':encodeURIComponent(file.name)},body:file});const a=await res.json();if(!res.ok)throw Error(a.error);if(!asset(a.id))project.assets.push(a);return a}
function pickFile(accept,callback,multiple=false){const input=$('#file');input.accept=accept;input.multiple=multiple;input.value='';input.onchange=()=>{if(input.files.length)Promise.resolve(callback(multiple?[...input.files]:input.files[0])).catch(e=>toast(e.message))};input.click()}
