function closeModal(){$('#dialog').close()}
function localKey(){return 'director-recovery-'+project.id}
function changed(){dirty=true;changeCount++;saveError=false;$('#save-status').className='save-status';$('#save-status').textContent='● Saving…';project.view={...project.view,deskView,deskSceneId,reviewVersionId,tab,selected,time:audio.currentTime||0};try{localStorage.setItem(localKey(),JSON.stringify({state:project,revision,savedAt:Date.now()}))}catch(e){toast('Browser recovery copy is full; disk autosave will continue.')}clearTimeout(saveTimer);saveTimer=setTimeout(()=>save().catch(()=>{}),750)}
async function save(label='Autosave'){
 if(saving){await saving;if(dirty||label!=='Autosave')return save(label);return}
 if(!project||(!dirty&&label==='Autosave'))return;
 const count=changeCount,pid=project.id,snapshot=structuredClone(project);saveError=false;
 saving=api('/api/projects/'+pid,{state:snapshot,expectedRevision:revision,label}).then(r=>{if(project.id!==pid)return;revision=r.revision;if(count===changeCount){dirty=false;localStorage.removeItem(localKey())}$('#save-status').textContent=`● Saved · v${revision}`;$('#save-status').className='save-status';updateProjectList();if(tab==='versions')renderVersions();}).catch(e=>{saveError=e.status===409||e.status===400;$('#save-status').textContent='● Save needs attention';$('#save-status').className='save-status error';toast(e.message);throw e}).finally(()=>{saving=null});
 await saving;if(dirty&&!saveError)return save();
}
async function updateProjectList(){projects=await api('/api/projects');$('#projects').innerHTML=projects.map(p=>`<button class="project-item ${project?.id===p.id?'active':''}" data-action="open" data-id="${p.id}"><strong>${esc(p.title)}</strong><small>${p.scenes} scenes · v${p.revision}</small></button>`).join('')}
async function openProject(pid,skipSave=false){suppressPauseSave=skipSave;pauseAudio();suppressPauseSave=false;if(!skipSave)await save();clearTimeout(saveTimer);const record=await api('/api/projects/'+pid);project=record.state;revision=record.revision;for(const k of ['scenes','lyrics','sections','assets','jobs','thumbnails','reuseExceptions','distinctReviews'])project[k]??=[];project.direction??={};project.guide??={};project.view??={};tab=project.view.tab||'story';deskView=project.view.deskView||'music';deskSceneId=project.view.deskSceneId||'';reviewVersionId=project.view.reviewVersionId||'';compareSelection=['',''];selected=project.view.selected||project.scenes[0]?.id;dirty=false;saveError=false;loopRange=null;undoStack=[];redoStack=[];$('#zoom').value=project.view.zoom??Math.max(1,Math.min(16,Math.ceil(duration()/75*4)/4));$('#snap').value=project.view.snap??0.1;$('#follow').checked=project.view.follow!==false;$('#remote-update').innerHTML='';localStorage.setItem('director-current',pid);render();await updateProjectList();await loadAudio();$('#save-status').textContent=`● Saved · v${revision}`;const recovery=localStorage.getItem(localKey());$('#recovery').innerHTML=recovery?'<div class="notice">An unsaved recovery copy is available. <button data-action="recover">Review and recover</button> <button data-action="discardRecovery">Keep saved version</button></div>':''}
