function renderTabs(){const items=[['story','Story & scenes',project.scenes.length],['lyrics','Timed lyrics',project.lyrics.length],['vision','Video vision'],['board','Storyboard'],['desk','Directing desk'],['guide','Visual guide'],['preview','Preview'],['production','Production'],['versions','History']];$('#tabs').innerHTML=items.map(([key,title,count])=>`<button class="tab ${tab===key?'active':''}" data-action="tab" data-tab="${key}">${title}${count!==undefined?` <span class="count">${count}</span>`:''}</button>`).join('')}
