function sceneStats(){const tally={};for(const s of project.scenes)tally[s.role]=(tally[s.role]||0)+s.end-s.start;return Object.entries(tally).map(([k,v])=>`<span><strong>${v.toFixed(1)}s</strong> ${esc(k)}</span>`).join('')}
function inspector(s){const i=sceneIndex(),p='scenes.'+i;const lyric=project.lyrics.filter(l=>l.start<s.end&&l.end>s.start).map(l=>l.text).join(' / ');return `<div class="inspector"><div class="inspector-top"><h2>Scene ${i+1} of ${project.scenes.length}</h2><span class="badge ${esc(s.status)}">${esc(s.status||'idea')}</span></div>${sceneNavigation(s)}${lyric?`<div class="scene-lyrics">${esc(lyric)}</div>`:''}<div class="form-grid"><div class="full">${field('Scene title',p+'.title',s.title,'The moment that matters')}</div>${sceneTimingFields(s)}<label>Scene purpose<select data-path="${p}.role">${opts(roles,s.role)}</select></label><label>Decision<select data-path="${p}.status">${opts(['idea','needs discussion','locked'],s.status||'idea')}</select></label><label>Song section<select data-path="${p}.section">${opts(['Unmarked',...sections],s.section||'Unmarked')}</select></label>${field('Location',p+'.location',s.location,'Where are we?')}<div class="full">${field('Gag / emotion / story beat',p+'.emotion',s.emotion,'What should the audience feel?')}</div></div><div class="inspector-section"><h3>Performance & instruments</h3><div class="form-grid">${field('Who is singing?',p+'.singer',s.singer,'Georgia Belle')}${field('Primary instrument',p+'.primaryInstrument',s.primaryInstrument??(s.performers||[]).map(p=>p.instrument).filter(Boolean).join(' + '),'Featured instrument')}<label>Shot mode<select data-path="${p}.shotMode">${opts(['Cut','Lip Sync'],s.lipSync?'Lip Sync':'Cut')}</select></label></div><div id="performers">${(s.performers||[]).map((a,j)=>`<div class="performer-row"><input aria-label="Performer name" data-path="${p}.performers.${j}.name" value="${esc(a.name)}" placeholder="Performer"><input aria-label="Instrument" data-path="${p}.performers.${j}.instrument" value="${esc(a.instrument)}" placeholder="Instrument / role"><button data-action="removePerformer" data-index="${j}" title="Remove performer">×</button></div>`).join('')}</div><button class="text-button" data-action="addPerformer">＋ Add visible performer</button></div>${techniqueSection(s,p)}${studioSceneShortcut(s)}<div class="note-user">${area('What you envision · YOUR NOTES',p+'.userNotes',s.userNotes,'What happens, and what must stay?')}</div><div class="note-assistant">${area('ASSISTANT PROPOSALS',p+'.assistantNotes',s.assistantNotes,'Ideas from your assistant stay separate here.')}</div><div class="inspector-section">${s.motionPromptStatus==='needs rewrite'?'<div class="notice">The reference picture changed. Write a new motion prompt for this picture and the selected Cut / Lip Sync role. The previous prompt is retained in history.</div>':''}${area('Motion prompt',p+'.motionPrompt',s.motionPrompt,'Use the full performer name Georgia Belle.')}${area('Review / repair notes',p+'.reviewNotes',s.reviewNotes,'Notes tied to this scene, its picture or finished clip…')}<div class="scene-actions"><button data-action="playScene">▶ Play scene</button><button data-action="splitScene">Split at playhead</button><button data-action="moveEarlier" ${i===0?'disabled':''}>Move earlier</button><button data-action="moveLater" ${i===project.scenes.length-1?'disabled':''}>Move later</button><button data-action="mergeScene" ${i===project.scenes.length-1?'disabled':''}>Merge next</button><button class="danger" data-action="deleteScene">Delete</button></div></div></div>`}
