 $('#content').innerHTML=`<div class="section-toolbar"><div><h2>Your vision for the whole video</h2><p>The story, mood, hook and ending you want us to build toward.</p></div><button data-action="export">Export package ↗</button></div><div class="panel planning-text">${area('Overall video vision','concept',project.concept,'Describe the whole video in your own words. What happens in the hook? How does the story progress? What is the ending? What balance of story and band performance do you want?')}<p class="field-help">Autosaves as you write. Included in the package with your song, timed lyrics and storyboard.</p>${area('Must-have moments / production notes','productionNotes',project.productionNotes,'Important scenes, actions, transitions, continuity or things to avoid…')}</div>`;
