 import:()=>modal('Import a plan or complete project',`<p>Bring in assistant input, an edited project file, or a complete exported ZIP.</p><div class="notice">Every import is reviewed first. Conflicts default to keeping your current values, including your notes and performance assignments.</div><button class="primary wide" data-action="pickImport">Choose JSON or project ZIP</button><div class="divider"></div><label>Or paste assistant JSON<textarea id="import-json" rows="7" placeholder='{"schemaVersion":1,"scenes":[]}'></textarea></label><div class="dialog-actions"><button data-action="exampleImport">Download input example</button><button data-action="pasteImport">Review pasted input</button></div>`),pickImport:()=>pickFile('.json,.zip',prepareImport),pasteImport:()=>prepareImport(new File([$('#import-json').value],'assistant-input.json')),applyImport:async()=>{const choices={};$$('[data-import-change]').forEach(el=>choices[importData.review.changes[Number(el.dataset.importChange)].path]=el.checked);const r=await api('/api/import/apply',{token:importData.token,mode:$('#import-mode').value,projectId:project.id,expectedRevision:importData.expectedRevision,choices});dirty=false;closeModal();await openProject(r.state.id,true);toast('Import saved as version '+r.revision+'.')},
