 markDistinct:el=>{const x=window.auditReport.issues[Number(el.dataset.index)];const note=prompt('Record why these are genuinely different compositions (a crop, mirror or recolor is not different):');if(!note?.trim())return;project.distinctReviews.push({assets:x.assets,note:note.trim(),at:new Date().toISOString()});changed();showAudit()},reuseException:el=>{const x=window.auditReport.issues[Number(el.dataset.index)];const reason=prompt('Explicitly authorize this picture reuse for these two scenes. Enter your reason:');if(!reason?.trim())return;project.reuseExceptions.push({assets:x.assets,scenes:x.scenes,reason:reason.trim(),at:new Date().toISOString()});changed();showAudit()},
 connect:showConnection,copyConnection:async()=>{await navigator.clipboard.writeText(window.connectionText);toast('Connection instructions copied.')},closeDialog:closeModal,templates:showTemplates,applyTemplate:el=>{const type=el.dataset.template;const names={Comedy:['The setup','Trouble arrives','Escalation','The reveal','The payoff'],Story:['Introduce the world','A clear desire','The obstacle','Turning point','Resolution'],Dance:['The invitation','First move','The group joins','Solo feature','Final dance'],Performance:['Opening presence','Lead vocal','Instrument feature','Full ensemble','Final statement']}[type];const start=project.scenes.at(-1)?.end||0,available=project.duration>start?project.duration-start:40,step=available/names.length;names.forEach((n,i)=>{const s=newScene(start+i*step,start+(i+1)*step,n,type==='Dance'?'dance':type==='Performance'?(i===2?'instrument':'singing'):i===4&&type==='Comedy'?'gag':'story');s.assistantNotes=`${type} template idea. Adjust duration and action to the song.`;project.scenes.push(s)});selected=project.scenes.at(-names.length).id;closeModal();changed();render()},
